    q(2, '①(7)', 'スケッチのしかた', 'スケッチでかくのは、目に見えているものすべてか、観察対象の生物だけか。', T('観察対象の生物だけ', '観察対象の生物', '観察対象だけ', '観察対象', '観察する生物だけ', '観察する生物', '観察対象の生物のみ', '生物だけ'), '見えるものすべてをかくのではなく、観察対象の生物だけを正確にかく（教科書p6）。', tb=6, tbnote='スケッチで記録する', near=['すべて', '見えているものすべて'])
    q(2, '①(5)', 'スケッチのしかた', 'スケッチでは、細い線と何を使ってはっきりかくか。', T('小さな点', '点', '小さい点', 'てん'), '教科書p6のポイント：細い線と小さな点ではっきりかく。', tb=6, tbnote='ポイント')
    q(2, '①(5)', 'スケッチのしかた', 'スケッチで、してはいけないことを2つ書こう。', R((1, ['二重', '2重', 'にじゅう', '重ね']), (1, ['影', 'かげ'])), '線を二重がきしたり、影をつけたりしない（教科書p6）。', tb=6, tbnote='ポイント', example='線を二重がきすることと、影をつけること')
